// Set a session cookie with all security attributes
res.cookie('sessionId', token, {
  // HttpOnly: JavaScript cannot read this cookie
  // Prevents XSS from stealing the session token
  httpOnly: true,

  // Secure: cookie only sent over HTTPS, never HTTP
  // Prevents eavesdropping on unencrypted connections
  secure: process.env.NODE_ENV === 'production',

  // SameSite: controls when cookie is sent cross-site
  // 'strict' — never sent cross-site (breaks OAuth flows)
  // 'lax'    — sent on top-level navigation (GET), not POST (recommended)
  // 'none'   — always sent (requires Secure: true) — only for embeds
  sameSite: 'lax',

  // maxAge: cookie expires after this many milliseconds
  maxAge: 7 * 24 * 60 * 60 * 1000,  // 7 days

  // path: cookie only sent for this path prefix
  path: '/',
});

// INSECURE — never do this:
res.cookie('sessionId', token);  // Missing all security attributes
// → JavaScript can steal it (XSS)
// → Sent over HTTP (eavesdropping)
// → Sent cross-site (CSRF possible)

import helmet from 'helmet';

// Helmet sets all important security headers automatically
app.use(helmet());

// What helmet sets:

// Content-Security-Policy: controls what resources the browser loads
// Prevents XSS by blocking inline scripts and scripts from untrusted origins
// Content-Security-Policy: default-src 'self'; script-src 'self' https://cdn.myapp.com

// X-Frame-Options: DENY
// Prevents your page being embedded in an iframe (clickjacking prevention)
// Superseded by CSP frame-ancestors, but set both for compatibility

// X-Content-Type-Options: nosniff
// Prevents browser 'MIME sniffing' — a file served as text/plain won't run as JavaScript

// Strict-Transport-Security: max-age=31536000; includeSubDomains
// Forces HTTPS for 1 year — browser will refuse HTTP connections

// Referrer-Policy: strict-origin-when-cross-origin
// Controls how much URL info is sent in the Referer header to other sites

// Permissions-Policy: camera=(), microphone=(), geolocation=()
// Disables browser features your app doesn't need
